    final int lenSuffix = suffix.length();
    if (lenSuffix > lenStr) {
        return false;
    }

    if (ignoreCase) {
        str = str.toLowerCase();
        suffix = suffix.toLowerCase();
    }

    for (int i = 0; i < lenSuffix; i++) {
