public static final <V> void reverse(V[] arr, int from, int to) {
    if (from == to) return;
    if (from > to) {
        int temp = from;
        from = to;
        to = temp;
    }
    for (int i = from, j = to; i < j; i++, j--) {
        V temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }
}

