public static String applyRelativePath(String path, String relativePath) {
    String[] elements = path.split(File.separator);
    String[] relative = relativePath.split(File.separator);
    StringBuilder result = new StringBuilder();

    int pathIndex = 0;
    for (String part : relative) {
        if (part.startsWith("../") || part.equals("..")) {
            if (pathIndex > 0) {
                pathIndex--;
            }
        } else if (part.startsWith("./")) {
            continue;
        } else {
            if (pathIndex >= elements.length) {
                result.append(relativePath).append(File.separator);
            } else {
                result.append(elements[pathIndex++]).append(File.separator);
            }
        }
    }

    if (pathIndex < elements.length) {
        result.append(elements[pathIndex]);
    }

    return result.toString();
}

