public long readRawVarint64() throws IOException {
    byte[] buffer = new byte[8];
    int bytesRead;
    long result = 0;

    do {
        bytesRead = in.read(buffer);
        if (bytesRead == -1) {
            throw new EOFException("End of input reached while reading varint.");
        }

        for (int i = 0; i < bytesRead && result < Long.MAX_VALUE; i++) {
            result = (result << 7) | (buffer[i] & 0x7F);
        }
    } while (bytesRead == 8);

    return result;
}

